int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        bytes_processed++;

        switch ((byte >> 6) & 0x03) {
            case 0x00:
                // Type 0 processing
                break;
            case 0x01:
                // Type 1 processing
                if (p + 1 >= end)
                    return -1;
                facilities->source_address = *p++;
                facilities->source_call = *p++;
                bytes_processed += 2;
                break;
            case 0x02:
                if (p + 1 >= end)
                    return -1;
                facilities->dest_address = *p++;
                facilities->dest_call = *p++;
                bytes_processed += 2;
                break;
            case 0x03:
                // End of facilities
                return bytes_processed;
            default:
                return -1;
        }
    }

    if (*p == 0x00) {
        return bytes_processed + 1;
    }

    return -1;
}

int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *start = p;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        switch ((*p >> 6) & 0x03) {
            case 0x00:
                /* Length encoded facility */
                p++;
                processed++;
                if (p >= end) {
                    return -1;
                }
                break;
            case 0x01:
                /* Fixed length facility */
                p += 2;
                processed += 2;
                if (p > end) {
                    return -1;
                }
                break;
            case 0x02:
                /* Variable length facility */
                if (p + 1 >= end) {
                    return -1;
                }
                p += 3;
                processed += 3;
                break;
            case 0x03:
                /* Termination byte */
                return processed;
        }
        processed++;
    }

    if (p >= end) {
        return -1;
    }

    return processed;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int i = 0;
    unsigned char *start = p;

    while (i < len && *p != 0x00) {
        switch (((*p) >> 6) & 0x03) {
            case 0x00:
                p++;
                i++;
                break;
            case 0x01:
                if (i + 1 > len) {
                    return -1;
                }
                p += 2;
                i += 2;
                break;
            case 0x02:
                if (i + 3 > len) {
                    return -1;
                }
                facilities->source_addr = (*p) & 0x3F;
                p++;
                i++;
                facilities->source_call_length = *p;
                p++;
                if (facilities->source_call_length > 7) {
                    return -1;
                }
                for (int j = 0; j < facilities->source_call_length; j++) {
                    if (i >= len) {
                        return -1;
                    }
                    facilities->source_call[j] = *p;
                    p++;
                    i++;
                }
                break;
            case 0x03:
                if (i + 3 > len) {
                    return -1;
                }
                facilities->dest_addr = (*p) & 0x3F;
                p++;
                i++;
                facilities->dest_call_length = *p;
                p++;
                if (facilities->dest_call_length > 7) {
                    return -1;
                }
                for (int j = 0; j < facilities->dest_call_length; j++) {
                    if (i >= len) {
                        return -1;
                    }
                    facilities->dest_call[j] = *p;
                    p++;
                    i++;
                }
                break;
        }
    }

    if (i == 0 && *p == 0x00) {
        return -1;
    }

    return i;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;

    while (bytes_processed < len) {
        unsigned char byte = p[bytes_processed];

        if (byte == 0x00) {
            break;
        }

        int group_code = (byte >> 6) & 0x03;

        switch (group_code) {
            case 0x00:
            case 0x01:
            case 0x02:
                bytes_processed++;
                break;

            case 0x03:
                if (bytes_processed + 1 >= len) {
                    return -1;
                }

                unsigned char subfield_length = p[bytes_processed + 1];
                if (subfield_length > len - (bytes_processed + 2)) {
                    return -1;
                }

                switch (byte & 0x3F) {
                    case 0x01:
                        if (facilities->source_address_length + subfield_length > ROSE_ADDR_MAX) {
                            return -1;
                        }
                        facilities->source_address_length += subfield_length;
                        bytes_processed += 2 + subfield_length;
                        break;
                    case 0x02:
                        if (facilities->dest_address_length + subfield_length > ROSE_ADDR_MAX) {
                            return -1;
                        }
                        facilities->dest_address_length += subfield_length;
                        bytes_processed += 2 + subfield_length;
                        break;
                    default:
                        bytes_processed += 2 + subfield_length;
                        break;
                }

                break;

            default:
                return -1;
        }
    }

    if (bytes_processed > len) {
        return -1;
    }

    return bytes_processed;
}

int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    unsigned char *start = p;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char tag = *p++;

        switch ((tag >> 6) & 3) {
            case 0: /* Source address */
                if (p + 6 > end)
                    return -1;

                memcpy(facilities->source_address, p, 6);
                p += 6;
                break;

            case 1: /* Destination address */
                if (p + 6 > end)
                    return -1;

                memcpy(facilities->dest_address, p, 6);
                p += 6;
                break;

            case 2: /* Source callsign */
                if (p + 1 > end || *p > 7)
                    return -1;

                facilities->source_call_length = *p++;
                if (p + facilities->source_call_length > end)
                    return -1;

                memcpy(facilities->source_call, p, facilities->source_call_length);
                p += facilities->source_call_length;
                break;

            case 3: /* Destination callsign */
                if (p + 1 > end || *p > 7)
                    return -1;

                facilities->dest_call_length = *p++;
                if (p + facilities->dest_call_length > end)
                    return -1;

                memcpy(facilities->dest_call, p, facilities->dest_call_length);
                p += facilities->dest_call_length;
                break;
        }
    }

    if (p > end)
        return -1;

    return p - start;
}
